#pragma once

#include <cstdint>

namespace weasel::tsf {

// Tracks an eaten OnTestKey* call until its paired OnKey* call arrives.
//
// Repeated Test callbacks are deduplicated using key + message time to avoid
// swallowing a later physical key repeat. Test and Key callbacks, however,
// may be generated by separate TSF/IMM32 bridge paths with DIFFERENT
// GetMessageTime() values for the SAME physical key. Pair those only by vkey,
// just as the historically working CUAS/Qt implementation did: requiring an
// identical timestamp delivers every physical key to Rime twice.
// A swallowed Test without an OnKey callback can still leave a stale same-vkey
// pending state for a subsequent OnKey-only event; key-up, the next Test, or a
// focus change clears/replaces it. Do not trade universal double input for
// this narrower exceptional case.
struct PendingTestKeyState {
  bool IsDuplicateTest(std::uint32_t key, std::uint32_t message_time) const {
    return pending && vkey == key && test_message_time == message_time;
  }

  void Arm(std::uint32_t key, std::uint32_t message_time) {
    pending = true;
    vkey = key;
    test_message_time = message_time;
  }

  // Treat a matching vkey as the paired delivery, regardless of Test/Key
  // timestamps. Some TSF/IMM32 bridges change both lParam and message time.
  bool ConsumePairedKey(std::uint32_t key) {
    const bool duplicate = pending && vkey == key;
    Clear();
    return duplicate;
  }

  void Clear() {
    pending = false;
    vkey = 0;
    test_message_time = 0;
  }

  bool pending = false;
  std::uint32_t vkey = 0;
  std::uint32_t test_message_time = 0;
};

}  // namespace weasel::tsf
